"""Arcade arena floor scatter tiles (WP-tile-floor; repainted 2026-11-13 for the painted floors). Original art generated by this
script (no legacy pixels used).
Run: python3 tools/assets/tile-gen/tilefloor.py public/assets/img/tilefloor.png   (needs Pillow + numpy; fixed seed and a
deterministic quantiser, so the output is byte-identical)
Atlas: 8 columns x 4 rows of 32x32 RGBA tiles, rows in stage order (fire, water, earth, air). The floor itself is now one
painted image per stage (arenafloor.png, tools/assets/stage-gen/arena-floor.py); these tiles only scatter sparse details over
it, so columns 0-3 (the common picks, src/game/fx/terrain-tiles.ts) are fully transparent and columns 4-7 are small details
with feathered alpha that fades to nothing before the tile edge: no grid can show. Each detail is drawn 4x and averaged down.
Grim and desaturated like the floors: fire cinders and a hairline ember crack, water a puddle glint and drowned weed, earth
pebbles and a dry grass tuft, air a lost feather and a scratched sky-rune.
"""
import sys
import numpy as np
from PIL import Image, ImageDraw

T = 32
S = 4  # supersampling
COLS = 8
ROWS = 4


def canvas():
    return Image.new("RGBA", (T * S, T * S), (0, 0, 0, 0))


def down(im):
    """Average the 4x drawing down with premultiplied alpha (no dark fringes), then fade the outer 3 px to nothing."""
    a = np.asarray(im, np.float32) / 255.0
    rgb, al = a[..., :3] * a[..., 3:], a[..., 3:]
    pool = lambda x: x.reshape(T, S, T, S, -1).mean((1, 3))  # noqa: E731
    rgb, al = pool(rgb), pool(al)
    u = np.minimum(np.arange(T), np.arange(T)[::-1]).astype(np.float32)
    edge = np.clip((u - 1) / 3, 0, 1)
    al = al * (edge[:, None] * edge[None, :])[..., None]
    rgb = np.where(al > 0, rgb / np.maximum(pool(a[..., 3:]), 1e-6), 0)
    return np.concatenate([np.clip(rgb, 0, 1) * 255, al * 255], -1).round().astype(np.uint8)


def soft(rng, im, pts, col, r, a):
    """A cluster of soft round blobs (pebbles, cinders, ash): radius r (tile px), alpha a."""
    d = ImageDraw.Draw(im)
    for x, y in pts:
        rr = r * (0.6 + 0.6 * rng.random())
        for k in range(4, 0, -1):  # a feathered disc: 4 rings, the edge the faintest
            q = rr * k / 4 * S
            d.ellipse([x * S - q, y * S - q, x * S + q, y * S + q], fill=col + (int(a * (1.15 - k * 0.22) * 255),))


def line(im, pts, col, w, a):
    ImageDraw.Draw(im).line([(x * S, y * S) for x, y in pts], fill=col + (int(a * 255),), width=int(w * S), joint="curve")


def walk(rng, x, y, dx, dy, n, jit):
    pts = [(x, y)]
    for _ in range(n):
        x, y = x + dx + rng.normal(0, jit), y + dy + rng.normal(0, jit)
        pts.append((x, y))
    return pts


def fire(k, rng):
    im = canvas()
    if k == 4:  # a hairline ember crack: dark scar, a thin glowing core
        p = walk(rng, 6, 10, 3.6, 2.0, 6, 1.2)
        line(im, p, (20, 12, 12), 3.0, 0.55)
        line(im, p, (196, 84, 26), 1.0, 0.75)
    elif k == 5:  # cinders: a few dull coals, one still warm
        soft(rng, im, [(10, 12), (19, 18), (14, 22), (23, 11)], (34, 26, 26), 2.2, 0.8)
        soft(rng, im, [(19, 18)], (170, 70, 24), 1.0, 0.8)
    elif k == 6:  # an ash drift
        soft(rng, im, [(8 + rng.random() * 16, 10 + rng.random() * 12) for _ in range(9)], (118, 108, 104), 2.6, 0.22)
    else:  # a scorch mark with glints
        soft(rng, im, [(16, 16)], (12, 8, 8), 9.0, 0.42)
        for _ in range(4):
            soft(rng, im, [(10 + rng.random() * 12, 10 + rng.random() * 12)], (210, 110, 40), 0.5, 0.7)
    return down(im)


def water(k, rng):
    im = canvas()
    if k == 4:  # a puddle glint: a dark film with a cold highlight
        soft(rng, im, [(16, 17)], (8, 22, 30), 8.0, 0.4)
        line(im, [(10, 15), (16, 14), (22, 15)], (150, 200, 210), 0.8, 0.45)
    elif k == 5:  # drowned weed
        for x in (11, 15, 19, 22):
            line(im, walk(rng, x, 25, rng.normal(0, 0.6), -2.6, 4, 0.5), (26, 52, 40), 1.3, 0.75)
    elif k == 6:  # a faint ripple
        d = ImageDraw.Draw(im)
        for r, a in ((9, 0.22), (5, 0.32)):
            d.ellipse([(16 - r) * S, (16 - r * 0.45) * S, (16 + r) * S, (16 + r * 0.45) * S], outline=(130, 186, 198, int(a * 255)), width=S)
    else:  # wet pebbles with a rim of light
        soft(rng, im, [(11, 14), (20, 19), (15, 21)], (20, 34, 40), 2.6, 0.85)
        soft(rng, im, [(10.4, 13.2), (19.4, 18.2), (14.4, 20.2)], (120, 160, 168), 0.8, 0.6)
    return down(im)


def earth(k, rng):
    im = canvas()
    if k == 4:  # pebbles, lit from the top left
        pts = [(9, 11), (20, 9), (15, 20), (23, 22)]
        soft(rng, im, [(x + 0.8, y + 1.0) for x, y in pts], (14, 12, 8), 2.8, 0.6)
        soft(rng, im, pts, (100, 92, 74), 2.2, 0.9)
        soft(rng, im, [(x - 0.6, y - 0.7) for x, y in pts], (150, 140, 112), 0.9, 0.6)
    elif k == 5:  # a dry grass tuft
        for i in range(7):
            line(im, walk(rng, 13 + i * 1.2, 24, (i - 3) * 0.8, -2.6, 3, 0.4), (92, 92, 52) if i % 2 else (58, 66, 34), 1.0, 0.8)
    elif k == 6:  # a crack in packed earth
        line(im, walk(rng, 5, 8, 3.4, 3.0, 6, 1.2), (14, 11, 8), 1.4, 0.7)
    else:  # a moss clump with a spore
        soft(rng, im, [(13 + rng.random() * 6, 13 + rng.random() * 6) for _ in range(5)], (44, 58, 26), 3.0, 0.6)
        soft(rng, im, [(17, 15)], (120, 156, 76), 0.6, 0.8)
    return down(im)


def air(k, rng):
    im = canvas()
    if k == 4:  # a lost feather
        line(im, [(8, 23), (24, 9)], (200, 198, 214), 0.7, 0.75)
        for t in np.linspace(0.15, 0.85, 8):
            x, y = 8 + 16 * t, 23 - 14 * t
            line(im, [(x, y), (x - 2.5, y - 2.8)], (176, 174, 196), 0.6, 0.5)
            line(im, [(x, y), (x + 2.8, y + 2.4)], (176, 174, 196), 0.6, 0.5)
    elif k == 5:  # a scratched sky-rune
        d = ImageDraw.Draw(im)
        d.arc([8 * S, 8 * S, 24 * S, 24 * S], 30, 320, fill=(40, 40, 60, 140), width=S)
        line(im, [(16, 9), (16, 23)], (40, 40, 60), 0.9, 0.5)
    elif k == 6:  # a drift of dust
        soft(rng, im, [(6 + rng.random() * 20, 12 + rng.random() * 8) for _ in range(10)], (214, 212, 230), 1.6, 0.16)
    else:  # a chip in the stone, lit edge
        soft(rng, im, [(16, 16)], (34, 34, 52), 3.4, 0.55)
        line(im, [(13, 13.6), (18.4, 13)], (210, 206, 226), 0.7, 0.55)
    return down(im)


def main(out):
    rng = np.random.default_rng(20261113)
    sheet = np.zeros((ROWS * T, COLS * T, 4), np.uint8)
    for row, paint in enumerate((fire, water, earth, air)):
        for k in range(4, COLS):
            sheet[row * T:(row + 1) * T, k * T:(k + 1) * T] = paint(k, rng)
    Image.fromarray(sheet, "RGBA").save(out, optimize=True)


main(sys.argv[1])
